# Taurus prompt for bash, in the style of the oh-my-zsh "ys" theme, colored with the active Taurus theme.
# Generated by Taurus from src/assets/matugen/apps/bash/prompt.sh: changes here are overwritten.
case $- in *i*) ;; *) return ;; esac
# A prompt manager (Starship, oh-my-posh) already owns PS1: leave it alone.
[ -n "${STARSHIP_SHELL:-}" ] || [ -n "${POSH_THEME:-}" ] && return

__taurus_accent=$'\001\e[1;38;2;{{colors.primary.default.red}};{{colors.primary.default.green}};{{colors.primary.default.blue}}m\002'
__taurus_user=$'\001\e[38;2;{{colors.primary.default.red}};{{colors.primary.default.green}};{{colors.primary.default.blue}}m\002'
__taurus_host=$'\001\e[38;2;{{colors.tertiary.default.red}};{{colors.tertiary.default.green}};{{colors.tertiary.default.blue}}m\002'
__taurus_dir=$'\001\e[1;38;2;{{colors.secondary.default.red}};{{colors.secondary.default.green}};{{colors.secondary.default.blue}}m\002'
__taurus_branch=$'\001\e[38;2;{{colors.primary.default.red}};{{colors.primary.default.green}};{{colors.primary.default.blue}}m\002'
__taurus_dirty=$'\001\e[38;2;{{colors.error.default.red}};{{colors.error.default.green}};{{colors.error.default.blue}}m\002'
__taurus_clean=$'\001\e[38;2;{{colors.tertiary.default.red}};{{colors.tertiary.default.green}};{{colors.tertiary.default.blue}}m\002'
__taurus_muted=$'\001\e[38;2;{{colors.outline.default.red}};{{colors.outline.default.green}};{{colors.outline.default.blue}}m\002'
__taurus_sign=$'\001\e[1;38;2;{{colors.error.default.red}};{{colors.error.default.green}};{{colors.error.default.blue}}m\002'
__taurus_reset=$'\001\e[0m\002'

__taurus_git() {
    local b
    b=$(git symbolic-ref --short HEAD 2>/dev/null || git rev-parse --short HEAD 2>/dev/null) || return
    if [ -n "$(git status --porcelain 2>/dev/null)" ]; then
        printf ' %son git:%s%s %sx' "$__taurus_muted" "$__taurus_branch" "$b" "$__taurus_dirty"
    else
        printf ' %son git:%s%s %so' "$__taurus_muted" "$__taurus_branch" "$b" "$__taurus_clean"
    fi
}

# user at host in dir on git:branch x [time] $
PS1='${__taurus_accent}#${__taurus_reset} ${__taurus_user}\u ${__taurus_muted}at ${__taurus_host}\h ${__taurus_muted}in ${__taurus_dir}\w${__taurus_reset}$(__taurus_git) ${__taurus_muted}[\t]${__taurus_reset} ${__taurus_sign}\$ ${__taurus_reset}'
